insert into public.questoes (owner, dados) values
(null, '{"tipo":"CE","enunciado":"A casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial.","alternativas":[],"gabarito":"C","comentario":"Certo. O item reproduz o art. 5º, XI, da CF/88. Atenção: a determinação judicial só autoriza o ingresso durante o dia; flagrante, desastre e socorro autorizam a qualquer hora.","fundamento":"CF/88, art. 5º, XI — a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial.","disciplina":"Direito Constitucional","assunto":"Direitos e garantias fundamentais","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"Conforme a Constituição Federal, a criação de associações e, na forma da lei, a de cooperativas dependem de autorização do poder público.","alternativas":[],"gabarito":"E","comentario":"Errado. A CF diz exatamente o contrário: a criação de associações e de cooperativas independe de autorização, sendo vedada a interferência estatal em seu funcionamento.","fundamento":"CF/88, art. 5º, XVIII — a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento.","disciplina":"Direito Constitucional","assunto":"Direitos e garantias fundamentais","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"São fundamentos da República Federativa do Brasil, nos termos do art. 1º da Constituição Federal, EXCETO:","alternativas":["a soberania.","a cidadania.","o pluralismo político.","a garantia do desenvolvimento nacional.","os valores sociais do trabalho e da livre iniciativa."],"gabarito":3,"comentario":"Gabarito D. Garantir o desenvolvimento nacional é objetivo fundamental (art. 3º, II), não fundamento. Os fundamentos do art. 1º são: soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político (SoCiDiVaPlu).","fundamento":"CF/88, art. 1º, I a V, e art. 3º, II.","disciplina":"Direito Constitucional","assunto":"Princípios fundamentais","banca":"Modelo · estilo FGV","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A Constituição Federal poderá ser emendada mediante proposta de um terço, no mínimo, dos membros da Câmara dos Deputados ou do Senado Federal.","alternativas":[],"gabarito":"C","comentario":"Certo. É uma das três iniciativas de PEC, ao lado do Presidente da República e de mais da metade das Assembleias Legislativas, cada uma pela maioria relativa de seus membros.","fundamento":"CF/88, art. 60, I a III.","disciplina":"Direito Constitucional","assunto":"Processo legislativo","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A proposta de emenda constitucional será discutida e votada em cada Casa do Congresso Nacional, em dois turnos, considerando-se aprovada se obtiver, em ambos, maioria absoluta dos votos dos respectivos membros.","alternativas":[],"gabarito":"E","comentario":"Errado. O quórum de aprovação da PEC é de três quintos dos votos dos membros de cada Casa, em dois turnos. Maioria absoluta é o quórum de lei complementar.","fundamento":"CF/88, art. 60, § 2º — a proposta será discutida e votada em cada Casa do Congresso Nacional, em dois turnos, considerando-se aprovada se obtiver, em ambos, três quintos dos votos dos respectivos membros.","disciplina":"Direito Constitucional","assunto":"Processo legislativo","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"Para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública, a Constituição prevê:","alternativas":["a ação popular.","o mandado de injunção.","o mandado de segurança.","a ação civil pública.","o habeas data."],"gabarito":2,"comentario":"Gabarito C. O mandado de segurança tem caráter residual: protege direito líquido e certo não amparado por HC ou HD.","fundamento":"CF/88, art. 5º, LXIX.","disciplina":"Direito Constitucional","assunto":"Remédios constitucionais","banca":"Modelo · estilo FCC","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"O direito da administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em cinco anos, contados da data em que foram praticados, salvo comprovada má-fé.","alternativas":[],"gabarito":"C","comentario":"Certo. Reproduz o art. 54 da Lei nº 9.784/1999. Havendo má-fé comprovada, não se aplica o prazo decadencial.","fundamento":"Lei nº 9.784/1999, art. 54.","disciplina":"Direito Administrativo","assunto":"Processo administrativo","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A administração pública direta e indireta obedecerá aos princípios da legalidade, impessoalidade, moralidade, publicidade e economicidade, expressamente previstos no caput do art. 37 da Constituição Federal.","alternativas":[],"gabarito":"E","comentario":"Errado. O quinto princípio expresso no caput do art. 37 é a eficiência (LIMPE), incluído pela EC nº 19/1998. A economicidade aparece no art. 70, no controle externo.","fundamento":"CF/88, art. 37, caput — legalidade, impessoalidade, moralidade, publicidade e eficiência.","disciplina":"Direito Administrativo","assunto":"Princípios","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"De acordo com a Lei nº 8.112/1990, a posse ocorrerá no prazo de quantos dias contados da publicação do ato de provimento?","alternativas":["15 dias.","30 dias.","45 dias.","60 dias.","90 dias."],"gabarito":1,"comentario":"Gabarito B. Posse: 30 dias da publicação do ato de provimento. Não confunda com o exercício: 15 dias contados da posse.","fundamento":"Lei nº 8.112/1990, art. 13, § 1º, e art. 15, § 1º.","disciplina":"Direito Administrativo","assunto":"Lei nº 8.112/1990","banca":"Modelo · estilo FCC","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"É de quinze dias o prazo para o servidor empossado em cargo público entrar em exercício, contados da data da posse.","alternativas":[],"gabarito":"C","comentario":"Certo. Art. 15, § 1º, da Lei nº 8.112/1990.","fundamento":"Lei nº 8.112/1990, art. 15, § 1º.","disciplina":"Direito Administrativo","assunto":"Lei nº 8.112/1990","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"O atributo pelo qual o ato administrativo se impõe a terceiros, independentemente de sua concordância, denomina-se:","alternativas":["presunção de legitimidade.","imperatividade.","autoexecutoriedade.","tipicidade.","motivação."],"gabarito":1,"comentario":"Gabarito B. Imperatividade (poder extroverso) é a imposição unilateral de obrigações. Autoexecutoriedade é executar o ato sem recorrer ao Judiciário; motivação é requisito de forma, não atributo.","fundamento":"Doutrina majoritária (Di Pietro, Carvalho Filho): atributos — presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade.","disciplina":"Direito Administrativo","assunto":"Atos administrativos","banca":"Modelo · estilo FGV","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada.","alternativas":[],"gabarito":"C","comentario":"Certo. Literalidade do art. 3º do CTN. Multa não é tributo porque é sanção de ato ilícito.","fundamento":"CTN, art. 3º.","disciplina":"Direito Tributário","assunto":"Conceito de tributo","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A natureza jurídica específica do tributo é determinada pela destinação legal do produto da sua arrecadação.","alternativas":[],"gabarito":"E","comentario":"Errado. Pelo art. 4º do CTN, a natureza jurídica específica é determinada pelo fato gerador, sendo irrelevantes a denominação e a destinação legal do produto da arrecadação.","fundamento":"CTN, art. 4º, I e II.","disciplina":"Direito Tributário","assunto":"Espécies tributárias","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"Nos termos do CTN, o direito de a Fazenda Pública constituir o crédito tributário extingue-se após:","alternativas":["2 anos.","3 anos.","5 anos.","10 anos.","20 anos."],"gabarito":2,"comentario":"Gabarito C. A decadência ocorre em 5 anos (art. 173). A prescrição da ação de cobrança também é de 5 anos, contados da constituição definitiva (art. 174).","fundamento":"CTN, art. 173 e art. 174.","disciplina":"Direito Tributário","assunto":"Decadência","banca":"Modelo · estilo FCC","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"Excluem o crédito tributário a isenção e a anistia.","alternativas":[],"gabarito":"C","comentario":"Certo. As duas únicas hipóteses de exclusão estão no art. 175 do CTN.","fundamento":"CTN, art. 175, I e II.","disciplina":"Direito Tributário","assunto":"Crédito tributário","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A moratória e o parcelamento são modalidades de extinção do crédito tributário.","alternativas":[],"gabarito":"E","comentario":"Errado. Moratória e parcelamento suspendem a exigibilidade do crédito tributário (art. 151, I e VI). A extinção está no art. 156.","fundamento":"CTN, art. 151, I e VI.","disciplina":"Direito Tributário","assunto":"Crédito tributário","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"Suspendem a exigibilidade do crédito tributário as hipóteses a seguir, EXCETO:","alternativas":["a moratória.","o depósito do seu montante integral.","as reclamações e os recursos, nos termos das leis reguladoras do processo tributário administrativo.","a concessão de medida liminar em mandado de segurança.","a compensação."],"gabarito":4,"comentario":"Gabarito E. A compensação extingue o crédito tributário (art. 156, II). As demais estão no art. 151 (MODERECOLIPA).","fundamento":"CTN, art. 151 e art. 156, II.","disciplina":"Direito Tributário","assunto":"Crédito tributário","banca":"Modelo · estilo FGV","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"É vedado à União, aos Estados, ao Distrito Federal e aos Municípios cobrar tributos no mesmo exercício financeiro em que haja sido publicada a lei que os instituiu ou aumentou.","alternativas":[],"gabarito":"C","comentario":"Certo. Princípio da anterioridade anual (art. 150, III, b). Some-se a ele a noventena da alínea c, com as exceções do § 1º.","fundamento":"CF/88, art. 150, III, b.","disciplina":"Direito Tributário","assunto":"Limitações ao poder de tributar","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"De acordo com a Lei Complementar nº 87/1996, o ICMS incide sobre a entrada de mercadoria ou bem importados do exterior por pessoa física ou jurídica, ainda que não seja contribuinte habitual do imposto, qualquer que seja a sua finalidade.","alternativas":[],"gabarito":"C","comentario":"Certo. Art. 2º, § 1º, I, da LC nº 87/1996, com a redação da LC nº 114/2002.","fundamento":"LC nº 87/1996, art. 2º, § 1º, I.","disciplina":"Legislação Tributária — ICMS","assunto":"Incidência","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"Conforme a Lei Complementar nº 87/1996, o ICMS incide sobre operações e prestações que destinem ao exterior mercadorias, inclusive produtos primários e produtos industrializados semielaborados, ou serviços.","alternativas":[],"gabarito":"E","comentario":"Errado. O art. 3º, II, da LC nº 87/1996 prevê a não incidência nas exportações, e a CF (art. 155, § 2º, X, a) assegura a manutenção do crédito das operações anteriores.","fundamento":"LC nº 87/1996, art. 3º, II; CF/88, art. 155, § 2º, X, a.","disciplina":"Legislação Tributária — ICMS","assunto":"Não incidência","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"Sobre o ICMS, assinale a afirmativa correta.","alternativas":["É imposto cumulativo, incidindo sobre o valor total de cada operação.","É não cumulativo, compensando-se o que for devido em cada operação com o montante cobrado nas anteriores pelo mesmo ou outro Estado ou pelo Distrito Federal.","A isenção ou não incidência implica crédito para compensação com o montante devido nas operações seguintes, salvo disposição em contrário.","Incide sobre o ouro, inclusive quando definido em lei como ativo financeiro ou instrumento cambial.","As alíquotas aplicáveis às operações interestaduais são fixadas por lei complementar."],"gabarito":1,"comentario":"Gabarito B (art. 155, § 2º, I). C está errada: a isenção ou não incidência não implica crédito (art. 155, § 2º, II, a). D: o ouro ativo financeiro sujeita-se só ao IOF (art. 153, § 5º). E: as alíquotas interestaduais são fixadas por resolução do Senado Federal (art. 155, § 2º, IV).","fundamento":"CF/88, art. 155, § 2º, I, II, IV; art. 153, § 5º.","disciplina":"Legislação Tributária — ICMS","assunto":"Princípios do ICMS","banca":"Modelo · estilo FGV","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"É assegurado ao contribuinte substituído o direito à restituição do valor do imposto pago por força da substituição tributária, correspondente ao fato gerador presumido que não se realizar.","alternativas":[],"gabarito":"C","comentario":"Certo. Art. 10 da LC nº 87/1996, em linha com o art. 150, § 7º, da CF. O STF (RE 593.849, Tema 201) também admite a restituição quando a base de cálculo efetiva for inferior à presumida.","fundamento":"LC nº 87/1996, art. 10; CF/88, art. 150, § 7º.","disciplina":"Legislação Tributária — ICMS","assunto":"Substituição tributária","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"Assinale a alternativa em que o acento indicativo de crase está empregado de acordo com a norma-padrão.","alternativas":["Fui à pé ao trabalho.","Entregou o relatório à ela.","Refiro-me à diretora do setor.","Começou à chover no fim da tarde.","Estava disposto à colaborar."],"gabarito":2,"comentario":"Gabarito C. \"Referir-se a\" + \"a diretora\" = à. Não há crase antes de palavra masculina (pé), de pronome pessoal (ela) nem de verbo (chover, colaborar).","fundamento":"Gramática normativa: crase = preposição a + artigo a(s).","disciplina":"Língua Portuguesa","assunto":"Crase","banca":"Modelo · estilo FCC","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"Na frase \"Fazem dois anos que ele saiu do órgão\", a concordância verbal está de acordo com a norma-padrão.","alternativas":[],"gabarito":"E","comentario":"Errado. O verbo fazer indicando tempo decorrido é impessoal e fica no singular: \"Faz dois anos que ele saiu\".","fundamento":"Gramática normativa: verbos impessoais (haver = existir; fazer = tempo).","disciplina":"Língua Portuguesa","assunto":"Concordância verbal","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"Assinale a frase em que a regência verbal segue a norma-padrão.","alternativas":["Assisti o filme ontem à noite.","Prefiro estudar do que trabalhar.","Aspiro a um cargo público.","Obedeça o regulamento interno.","Esqueci do compromisso."],"gabarito":2,"comentario":"Gabarito C. Aspirar, no sentido de almejar, exige a preposição a. Correções: assisti ao filme; prefiro estudar a trabalhar; obedeça ao regulamento; esqueci o compromisso ou esqueci-me do compromisso.","fundamento":"Gramática normativa: regência de assistir, preferir, aspirar, obedecer e esquecer.","disciplina":"Língua Portuguesa","assunto":"Regência verbal","banca":"Modelo · estilo FGV","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A negação da proposição \"Todos os auditores foram aprovados\" é \"Nenhum auditor foi aprovado\".","alternativas":[],"gabarito":"E","comentario":"Errado. A negação de \"todo A é B\" é \"algum A não é B\": \"Algum auditor não foi aprovado\".","fundamento":"Lógica: ~(∀x P(x)) ≡ ∃x ~P(x).","disciplina":"Raciocínio Lógico","assunto":"Negação de proposições","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"ME","enunciado":"A negação de \"Se chove, então a rua fica molhada\" é:","alternativas":["Se não chove, então a rua não fica molhada.","Chove e a rua não fica molhada.","Não chove ou a rua fica molhada.","Se a rua não fica molhada, então não chove.","Não chove e a rua fica molhada."],"gabarito":1,"comentario":"Gabarito B. ~(p → q) ≡ p ∧ ~q. A alternativa D é a contrapositiva, equivalente à proposição original, e não sua negação.","fundamento":"Lógica: ~(p → q) ≡ p ∧ ~q.","disciplina":"Raciocínio Lógico","assunto":"Condicional","banca":"Modelo · estilo FCC","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb),
(null, '{"tipo":"CE","enunciado":"A proposição p → q é logicamente equivalente a ~q → ~p.","alternativas":[],"gabarito":"C","comentario":"Certo. É a contrapositiva. Outra equivalência cobrada: p → q ≡ ~p ∨ q.","fundamento":"Lógica: p → q ≡ ~q → ~p ≡ ~p ∨ q.","disciplina":"Raciocínio Lógico","assunto":"Equivalências","banca":"Modelo · estilo CEBRASPE","ano":"","orgao":"","cargo":"","origem":"modelo","dificuldade":"média"}'::jsonb);
